(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.2)*12;
  const w1y = Math.cos(y*0.018-t*0.25)*18 + Math.sin(x*0.016+t*0.35)*12;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.025-t*0.5)*8 + Math.cos(sy*0.02+t*0.4)*6;
  const w2y = Math.cos(sy*0.025+t*0.45)*8 + Math.sin(sx*0.022-t*0.55)*6;
  const fx = sx + w2x, fy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*45, 0.085, 1.8]
  ];
  let aS=0, iS=0, hS=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    hS += Math.sin(d*f*1.3-t*sp*0.4+3.0)*0.5;
  }
  const act=aS/8, inh=iS/8, hab=hS/8;
  const bg = (Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2
    + Math.sin((fx+fy)*0.12+t*2.5)*0.2 + Math.sin((fx-fy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((fx-cx)**2+(fy-cy)**2), ang = Math.atan2(fy-cy, fx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const ripple = Math.sin(dist*0.08-t*3)*Math.exp(-dist*0.008)*0.3;
  const micro = (Math.sin(fx*0.3+t*4)*Math.sin(fy*0.3-t*3.5)
    + Math.sin((fx*0.5+fy*0.3)+t*5)*Math.sin((fx*0.3-fy*0.5)-t*4.5))*0.15;
  const rd1 = Math.tanh((act-inh*0.7+bg*0.3+spiral)*2.2);
  const rd2 = Math.tanh((inh-act*0.5+hab+ripple)*1.8);
  const rd3 = Math.tanh((act*inh*0.5+hab*0.8+micro)*2.5);
  const reaction = (rd1*0.5+rd2*0.3+rd3*0.2);
  const cell = Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)
    +Math.sin((fx+fy)*0.1+t)*0.5+Math.sin(fx*0.22-fy*0.18+t*0.7)*0.3)*1.5)*0.25;
  const vein = Math.abs(Math.sin(fx*0.08+Math.sin(fy*0.06+t)*2))*Math.abs(Math.sin(fy*0.07+Math.cos(fx*0.05+t)*2))*0.2;
  const blend = reaction*0.65+cell*0.2+vein*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,52],[12,42,88],[18,85,120],[28,135,140],[45,175,155],
    [180,195,80],[210,155,55],[195,95,65],[165,55,70],[120,30,60],
    [70,18,55],[30,10,45],[6,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.78+Math.sin(reaction*Math.PI)*0.22;
  const edge = Math.abs(reaction)>0.65?1.12:1.0;
  const glow = Math.max(0, 1-Math.abs(reaction)*2)*0.15;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*40)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*80)|0
  ];
}
